<?php
require_once __DIR__.'/includes/auth.php';require_once __DIR__.'/includes/functions.php';$pdo=aep_database();$id=(int)($_GET['id']??0);$stmt=$pdo->prepare('SELECT * FROM tasks WHERE id=?');$stmt->execute([$id]);$task=$stmt->fetch();if(!$task){http_response_code(404);exit('Task not found.');}$matters=$pdo->query('SELECT id,matter_reference,subject FROM matters ORDER BY updated_at DESC')->fetchAll();$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){aep_validate_csrf();$title=aep_post_string('title',300);$due=aep_post_string('due_date',10);if($title===''||($due!==''&&!preg_match('/^\d{4}-\d{2}-\d{2}$/',$due))){$error='Enter a task title and valid due date.';}else{$pdo->prepare('UPDATE tasks SET matter_id=?,title=?,description=?,status=?,due_date=?,updated_at=CURRENT_TIMESTAMP WHERE id=?')->execute([(int)($_POST['matter_id']??0)?:null,$title,aep_post_string('description',4000),aep_valid_status(aep_post_string('status',20),['open','in_progress','completed'],'open'),$due?:null,$id]);aep_log_activity($pdo,'Tasks','Updated '.$title);header('Location:task_view.php?id='.$id);exit;}}
$pageTitle='Edit Task | AEP';$activeNav='tasks';require __DIR__.'/includes/header.php';?><div class="card" style="max-width:820px;margin:auto"><h1>Edit Task</h1><?php if($error):?><p style="color:#b42318"><?php echo aep_h($error);?></p><?php endif;?><form method="post" class="grid grid-2" style="margin-top:18px"><?php echo aep_csrf_field();?><div><label>Task title *</label><input required name="title" value="<?php echo aep_h($task['title']);?>"></div><div><label>Matter</label><select name="matter_id"><option value="">Unlinked task</option><?php foreach($matters as $matter):?><option value="<?php echo $matter['id'];?>" <?php echo (int)$task['matter_id']===(int)$matter['id']?'selected':'';?>><?php echo aep_h($matter['matter_reference'].' — '.$matter['subject']);?></option><?php endforeach;?></select></div><div><label>Due date</label><input type="date" name="due_date" value="<?php echo aep_h($task['due_date']);?>"></div><div><label>Status</label><select name="status"><?php foreach(['open'=>'Open','in_progress'=>'In progress','completed'=>'Completed'] as $v=>$label):?><option value="<?php echo $v;?>" <?php echo $task['status']===$v?'selected':'';?>><?php echo $label;?></option><?php endforeach;?></select></div><div style="grid-column:1/-1"><label>Description</label><textarea name="description"><?php echo aep_h($task['description']);?></textarea></div><div class="actions"><button class="btn">Save changes</button><a class="btn secondary" href="task_view.php?id=<?php echo $id;?>">Cancel</a></div></form></div><?php require __DIR__.'/includes/footer.php';?>
